import { getBusinessForStop, getLoyaltyProgramForBusiness, getOfferForBusiness } from '../data/localMarketplace';
import { clearLocalEvents, getStorageKey, recordLocalEvent } from './localEvents';

export function seedTourDemoEvidence(tour, { clearEvents = true } = {}) {
  const businessStop = tour.stops?.find(stop => getBusinessForStop(tour.id, stop.id)) || tour.stops?.[0];
  const business = businessStop ? getBusinessForStop(tour.id, businessStop.id) : null;
  const offer = business ? getOfferForBusiness(business.id) : null;
  const loyaltyProgram = business ? getLoyaltyProgramForBusiness(business.id) : null;
  const savedStop = tour.stops?.find(stop => stop.id !== businessStop?.id) || businessStop;
  const businessStopIndex = tour.stops?.findIndex(stop => stop.id === businessStop?.id) ?? -1;
  const resumeIndex = businessStopIndex >= 0 ? Math.min((tour.stops?.length || 1) - 1, businessStopIndex + 1) : 0;

  if (clearEvents) clearLocalEvents();

  localStorage.setItem(getStorageKey('progress', tour.id), JSON.stringify(businessStop ? [businessStop.id] : []));
  localStorage.setItem(getStorageKey('saved-stops', tour.id), JSON.stringify(savedStop ? [savedStop.id] : []));
  localStorage.setItem(getStorageKey('offers', tour.id), JSON.stringify(offer ? [offer.id] : []));
  localStorage.setItem(getStorageKey('loyalty', tour.id), JSON.stringify(loyaltyProgram ? { [loyaltyProgram.id]: 1 } : {}));
  localStorage.setItem(getStorageKey('current-stop-index', tour.id), String(resumeIndex));
  localStorage.setItem(getStorageKey('field-note', tour.id), 'Synthetic demo seed: offer felt useful at the stop, loyalty was understandable, and this route needs field verification before publish.');
  localStorage.setItem(`tour-engine:offline-pack:${tour.id}`, JSON.stringify({
    savedAt: new Date().toISOString(),
    stops: tour.stops?.map(stop => ({ id: stop.id, title: stop.title })) || []
  }));

  if (businessStop) recordLocalEvent('stop_completed', { tourId: tour.id, stopId: businessStop.id, stopPosition: businessStopIndex + 1, sourceStopNumber: businessStop.number, seed: true });
  if (business && offer) recordLocalEvent('offer_activate', { tourId: tour.id, stopId: businessStop.id, businessId: business.id, offerId: offer.id, seed: true });
  if (business && loyaltyProgram) recordLocalEvent('loyalty_stamp_granted', { tourId: tour.id, stopId: businessStop.id, businessId: business.id, loyaltyProgramId: loyaltyProgram.id, stamps: 1, verificationMode: loyaltyProgram.verificationMode, seed: true });
  if (businessStop) recordLocalEvent('field_signal', { tourId: tour.id, stopId: businessStop.id, businessId: business?.id || null, signal: 'useful', note: 'Synthetic reviewer seed for evidence-page walkthrough.', seed: true });

  return {
    tourId: tour.id,
    businessStopId: businessStop?.id || null,
    resumePosition: resumeIndex + 1,
    offerId: offer?.id || null,
    loyaltyProgramId: loyaltyProgram?.id || null
  };
}

export function seedDemoEvidenceForTours(tours = []) {
  clearLocalEvents();
  return tours.map(tour => seedTourDemoEvidence(tour, { clearEvents: false }));
}

export function clearDemoEvidenceForTours(tours = []) {
  clearLocalEvents();

  for (const tour of tours) {
    ['progress', 'saved-stops', 'offers', 'loyalty', 'current-stop-index', 'field-note'].forEach(prefix => {
      localStorage.removeItem(getStorageKey(prefix, tour.id));
    });
    localStorage.removeItem(`tour-engine:offline-pack:${tour.id}`);
  }

  return { clearedTours: tours.map(tour => tour.id) };
}
